def orientations(cells):
    out=set()
    for refl in (1,-1):
      for k in range(4):
        pts=[]
        for r,c in cells:
          x,y=r,c*refl
          for _ in range(k): x,y=y,-x
          pts.append((x,y))
        mr=min(x for x,y in pts); mc=min(y for x,y in pts)
        out.add(tuple(sorted((x-mr,y-mc) for x,y in pts)))
    return [set(o) for o in out]
