 for r in range(h):
  for c in range(w):
   if grid[r][c]!=val or (r,c) in seen:continue
   q=[(r,c)];seen.add((r,c)); co=[]
   while q:
    x,y=q.pop();co.append((x,y))
    for dx,dy in ds:
     p=(x+dx,y+dy)
     if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==val:
      seen.add(p);q.append(p)
   cs.append(set(co))
 return cs
